// Exam-length reading forms for Annual Exam Study.
// Original prose, or public-domain Latin adapted and glossed for students.
// Questions and glosses are original. Sources are named on each passage.

function longExamQ(id, level, category, prompt, choices, answer, explanation, passageId, order, section) {
  const extra = { passageId, order };
  if (section) extra.section = section;
  return annualExamQ(id, level, category, prompt, choices, answer, explanation, extra);
}

